/**
 * Every module a replacement line names (`lib/<path>.js`), lib-relative, unique and sorted: the doors a
 * retired global now points at. The sdk build places each in the dist (sdk/frqtl-web/build.js), so a
 * repoint never names a file the published package lacks; a test holds every path to an existing file.
 * @returns {string[]}
 */
export function retiredModulePaths() {
    const out = new Set();
    for (const name of Object.keys(RETIRED_GLOBALS)) {
        for (const m of RETIRED_GLOBALS[name].matchAll(/\blib\/((?:frqtl|shim)\/[\w./-]+\.js)\b/g)) { out.add(m[1]); }
    }
    return Array.from(out).sort();
}
